using System;using System.IO;using System.Linq;using System.Security.Cryptography;using Newtonsoft.Json.Linq;using UnityEditor;using UnityEditor.Build.Reporting;using UnityEngine;using UnityEngine.Rendering;
public static class Native49FinalBuild {
 public static string VerifyCompilation(){Ready();return "OutsideAssets finalBuild helper compiled; native ready/stopped/clean. No build scheduled.";}
 static string Hash(string f){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(f))).Replace("-","").ToLowerInvariant();}
 static void Ready(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)throw new Exception("Actual ready/stopped required");if(GraphicsSettings.currentRenderPipeline==null)throw new Exception("Current URP required");for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene blocks build");var dirty=Resources.FindObjectsOfTypeAll<UnityEngine.Object>().Where(o=>EditorUtility.IsDirty(o)&&AssetDatabase.GetAssetPath(o).StartsWith("Assets/")&&(o is Material||o is GameObject)).ToArray();if(dirty.Length!=0)throw new Exception("Dirty material/prefab blocks build: "+string.Join(",",dirty.Select(AssetDatabase.GetAssetPath)));}
 public static string Schedule(){Ready();var pointer=JObject.Parse(File.ReadAllText("Tools/URPMigration/FinalAndroid-current.json"));string folder=(string)pointer["stage"];if(File.Exists(folder+"/request.json"))throw new Exception("Never overwrite/retry existing build stage");var pre=JObject.Parse(File.ReadAllText(folder+"/prebuild.json"));foreach(JObject guard in pre["criticalInputs"]){if(Hash((string)guard["path"])!=(string)guard["sha256"])throw new Exception("Critical preserved input drift "+guard["path"]);}
  var route=JObject.Parse(File.ReadAllText("Tools/URPMigration/FinalRun-current.json"));var observation=JObject.Parse(File.ReadAllText((string)route["observation"]));if(!(bool)observation["completed"]||!(bool)observation["sdkComplete"]||!(bool)observation["sdkResult"]||((JArray)observation["errors"]).Count!=0)throw new Exception("Normal180 survival/SDK ending gate");var loss=JObject.Parse(File.ReadAllText((string)pre["lossObservation"]));if(!(bool)loss["completed"]||!(bool)loss["depletionObserved"]||((JArray)loss["errors"]).Count!=0)throw new Exception("Normal health depletion gate");
  File.Copy("Tools/URPMigration/Native49FinalBuild.cs",folder+"/Native49FinalBuild.cs");File.WriteAllText(folder+"/request.json",new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["pid"]=System.Diagnostics.Process.GetCurrentProcess().Id,["prebuildSHA256"]=Hash(folder+"/prebuild.json"),["routeSHA256"]=Hash((string)route["observation"]),["lossSHA256"]=Hash((string)pre["lossObservation"]),["method"]="Root serialized heavy-build lease; deferred native Development Android BuildPipeline.BuildPlayer. No SaveAssets/global flush/source route replay."}.ToString());var at=EditorApplication.timeSinceStartup+2;EditorApplication.CallbackFunction tick=null;tick=()=>{if(EditorApplication.timeSinceStartup<at)return;EditorApplication.update-=tick;Build(folder);};EditorApplication.update+=tick;return folder;
 }
 static void Build(string folder){Ready();var profile=AssetDatabase.LoadMainAssetAtPath("Assets/Liminal/Resources/LimappConfig.asset");var script=new SerializedObject(profile).FindProperty("m_Script").objectReferenceValue as MonoScript;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(script,out string guid,out long id);File.WriteAllText(folder+"/native-before.json",new JObject{["pid"]=System.Diagnostics.Process.GetCurrentProcess().Id,["GPU"]=SystemInfo.graphicsDeviceType.ToString(),["graphicsAPIs"]=new JArray(PlayerSettings.GetGraphicsAPIs(BuildTarget.Android).Select(x=>x.ToString())),["profileClass"]=profile.GetType().FullName,["profileJSON"]=EditorJsonUtility.ToJson(profile),["profileScriptGUID"]=guid,["profileScriptLocalID"]=id,["profileScriptClass"]=script.GetClass().AssemblyQualifiedName,["modules"]=new JArray(AppDomain.CurrentDomain.GetAssemblies().Where(a=>new[]{"App000000000049","Liminal.SDK","LiminalSdk","Editor"}.Contains(a.GetName().Name)).Select(a=>new JObject{["assembly"]=a.GetName().Name,["MVID"]=a.ManifestModule.ModuleVersionId.ToString(),["location"]=a.Location})),["preloadedAssets"]=new JArray(PlayerSettings.GetPreloadedAssets().Select(o=>o==null?null:AssetDatabase.GetAssetPath(o)))}.ToString());string apk=folder+"/Experience49-URP.apk";var errors=new JArray();Application.LogCallback log=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(new JObject{["type"]=t.ToString(),["message"]=m,["stack"]=s});};Application.logMessageReceived+=log;
  try{var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/Scenes/The_Game.unity"},locationPathName=apk,target=BuildTarget.Android,options=BuildOptions.Development});var packed=new JArray();foreach(var p in report.packedAssets)foreach(var item in p.contents)if(item.type==typeof(MonoScript)||item.sourceAssetPath.EndsWith("Liminal.SDK.dll")||item.sourceAssetPath=="Assets/Liminal/Resources/LimappConfig.asset")packed.Add(new JObject{["packedAsset"]=p.shortPath,["packedID"]=item.id.ToString(),["offset"]=item.offset,["sourceAssetGUID"]=item.sourceAssetGUID.ToString(),["sourceAssetPath"]=item.sourceAssetPath,["packedSize"]=item.packedSize,["type"]=item.type==null?null:item.type.FullName});File.WriteAllText(folder+"/packed-script-profile-rows.json",packed.ToString());File.WriteAllText(folder+"/android-build.json",new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["result"]=report.summary.result.ToString(),["errors"]=report.summary.totalErrors,["warnings"]=report.summary.totalWarnings,["reportedTotalSize"]=report.summary.totalSize,["duration"]=report.summary.totalTime.ToString(),["apkSHA256"]=File.Exists(apk)?Hash(apk):null,["actualAPKBytes"]=File.Exists(apk)?new FileInfo(apk).Length:0,["buildGUID"]=report.summary.guid.ToString(),["messages"]=new JArray(report.steps.SelectMany(s=>s.messages).Select(m=>new JObject{["type"]=m.type.ToString(),["content"]=m.content})),["nativeErrors"]=errors}.ToString());}catch(Exception e){File.WriteAllText(folder+"/build-exception.txt",e.ToString());throw;}finally{Application.logMessageReceived-=log;File.WriteAllText(folder+"/native-terminal.json",new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["nativeErrors"]=errors,["limits"]="Actual BuildPlayer terminal, exact postbuild source/config/residue/provider/packedProfile checks follow separately. Physical Quest not exercised."}.ToString());}
 }
}
